/* Service worker: precaches the app so it works offline. Generated by scripts/build-web.mjs. */
const VERSION = "__VERSION__";
const ASSETS = __ASSETS__;
const CACHE = "rummy-trainer-" + VERSION;

self.addEventListener("install", event => {
    event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", event => {
    event.waitUntil(
        caches.keys()
            .then(keys => Promise.all(keys.filter(key => key.startsWith("rummy-trainer-") && key !== CACHE).map(key => caches.delete(key))))
            .then(() => self.clients.claim()),
    );
});

self.addEventListener("fetch", event => {
    const request = event.request;
    if (request.method !== "GET" || new URL(request.url).origin !== self.location.origin) return;
    if (request.mode === "navigate") {
        // network first for the page, so updates arrive quickly; cached page offline
        event.respondWith(
            fetch(request)
                .then(response => {
                    const copy = response.clone();
                    caches.open(CACHE).then(cache => cache.put("./", copy));
                    return response;
                })
                .catch(() => caches.match("./").then(cached => cached || caches.match("index.html"))),
        );
        return;
    }
    event.respondWith(caches.match(request).then(cached => cached || fetch(request)));
});
